const state = { loading: false, data: null, error: null };

function load(url) {
    state.loading = true;
    state.error = null;
    try {
        if (!url.startsWith("https://")) throw new Error("Faqat https qo'llanadi");
        state.data = { url };
    } catch (err) {
        state.error = err.message;
    } finally {
        state.loading = false;
    }
    return { ...state };
}

console.log(load("https://example.com"));
console.log(load("ftp://example.com"));

