let calls = 0;

function unstableTask() {
    calls++;
    if (calls < 3) throw new Error(`urinish ${calls} muvaffaqiyatsiz`);
    return "muvaffaqiyat";
}

function retry(task, attempts) {
    for (let i = 1; i <= attempts; i++) {
        try {
            return task();
        } catch (err) {
            console.log("Xato:", err.message);
            if (i === attempts) throw err;
        }
    }
}

console.log(retry(unstableTask, 5));

