function validateUser(user) {
    const issues = [];
    if (!user.name) issues.push({ field: "name", message: "ism kerak" });
    if (!/^\S+@\S+\.\S+$/.test(user.email ?? "")) issues.push({ field: "email", message: "email noto'g'ri" });
    if (!(user.age >= 18)) issues.push({ field: "age", message: "yosh kamida 18 bo'lishi kerak" });
    if (issues.length > 0) throw new ValidationError(issues);
    return user;
}

try {
    validateUser({ email: "aziz@", age: 15 });
} catch (err) {
    console.log(err.message);
    for (const { field, message } of err.issues) {
        console.log(` - ${field}: ${message}`);
    }
}

