const handleError = (err) => ({ status: 500, body: err.message });

function wrapAsync(handler) {
    return async (...args) => {
        try {
            return await handler(...args);
        } catch (err) {
            return handleError(err);
        }
    };
}

const getUser = wrapAsync(async (id) => {
