function serializeError(err) {
    if (!Error.isError(err)) return { value: String(err) };
    const data = { name: err.name, message: err.message };
    if (err.cause !== undefined) data.cause = serializeError(err.cause);
    return data;
}

function report(source, err, context = {}) {
    console.log(JSON.stringify({ level: "error", source, error: serializeError(err), ...context }));
}

