function transfer(from, to, amount) {
    if (typeof amount !== "number" || !Number.isFinite(amount)) {
        throw new TypeError(`amount son bo'lishi kerak: ${amount}`);
    }
    if (amount <= 0) throw new RangeError("amount musbat bo'lishi kerak");
    if (from === to) throw new Error("bir xil hisobga o'tkazib bo'lmaydi");
    return `${from} -> ${to}: ${amount}`;
}

