function readTheme(stored) {
    try {
        const parsed = JSON.parse(stored);
        if (!["light", "dark"].includes(parsed.theme)) throw new RangeError("noma'lum mavzu");
        return parsed.theme;
    } catch (err) {
        console.log("[warn] sozlama o'qilmadi:", err.name);
        return "light";
    }
}

console.log(readTheme('{"theme": "dark"}'));
console.log(readTheme("{buzuq"));
console.log(readTheme('{"theme": "pushti"}'));

function renderSafely(component, fallback) {
    try {
        return component();
    } catch (err) {
        console.log("[log] komponent xatosi:", err.message);
        return fallback(err);
    }
}

