function installGlobalHandlers(report) {
    if (typeof process !== "undefined" && typeof process.on === "function") {
        process.on("uncaughtException", (err) => report("uncaughtException", err));
        process.on("unhandledRejection", (reason) => report("unhandledRejection", reason));
    } else {
        globalThis.addEventListener("error", (event) => report("error", event.error));
        globalThis.addEventListener("unhandledrejection", (event) => report("unhandledrejection", event.reason));
    }
}

installGlobalHandlers((source, error) => {
    const message = error instanceof Error ? error.message : String(error);
    console.log(`[${source}] ${message}`);
});

