const resources = ["db", "cache", "server"];

function shutdown(signal) {
    console.log(`${signal} qabul qilindi, yopilmoqda...`);
    for (const name of [...resources].reverse()) {
        console.log(`  ${name} yopildi`);
    }
    process.exitCode = 0;
}

