function reportToServer(error, extra = {}) {
    const payload = JSON.stringify({ name: error.name, message: error.message, ...extra });
    const sent = navigator.sendBeacon("/api/errors", new Blob([payload], { type: "application/json" }));
    console.log("navbatga qo'yildi:", sent);
}

window.addEventListener("error", (event) => reportToServer(event.error, { type: "error" }));

