// HTML: <script src="app.js"></script>
const queue = [];

window.addEventListener("error", (event) => {
    queue.push({ message: event.error?.message ?? event.message });
});

document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden" && queue.length > 0) {
        navigator.sendBeacon("/api/errors", JSON.stringify(queue));
        console.log("yuborildi:", queue.length, "ta xato");
        queue.length = 0;
    }
});

